import heapq
from collections import Counter


class DisplayBook:
    def __init__(self, lot_size, mm_bid, mm_bid_qty, mm_ask, mm_ask_qty):
        self.lot = lot_size
        self.mm_bid, self.mm_bid_qty = mm_bid, mm_bid_qty
        self.mm_ask, self.mm_ask_qty = mm_ask, mm_ask_qty
        self.cnt = {True: Counter(), False: Counter()}
        self.heap = {True: [], False: []}  # bids stored negated
        self.orders = {}  # oid -> (is_bid, price, displayable)

    def _displayable(self, is_bid, price, qty):
        if qty % self.lot:
            return False
        if is_bid:
            return price > self.mm_bid or (price == self.mm_bid and qty > 0.05 * self.mm_bid_qty)
        return price < self.mm_ask or (price == self.mm_ask and qty > 0.05 * self.mm_ask_qty)

    def add(self, oid, ts, is_bid, price, qty):
        ok = self._displayable(is_bid, price, qty)
        self.orders[oid] = (is_bid, price, ok)
        if ok:
            self.cnt[is_bid][price] += 1
            heapq.heappush(self.heap[is_bid], -price if is_bid else price)
        return self.best()

    def cancel(self, oid, ts):
        if oid in self.orders:
            is_bid, price, ok = self.orders.pop(oid)
            if ok:
                self.cnt[is_bid][price] -= 1
        return self.best()

    def _top(self, is_bid):
        h, c = self.heap[is_bid], self.cnt[is_bid]
        while h and c[-h[0] if is_bid else h[0]] == 0:
            heapq.heappop(h)
        if not h:
            return None
        return -h[0] if is_bid else h[0]

    def best(self):
        b, a = self._top(True), self._top(False)
        bid = self.mm_bid if b is None else max(b, self.mm_bid)
        ask = self.mm_ask if a is None else min(a, self.mm_ask)
        return (bid, ask)
